            {
              "text": "His expertise lies in cybersecurity research and development, with skills in Python, Linux, and software design.",
              "claimIds": [
                "zaf-060",
                "zaf-063"
              ]
            },
            {
              "text": "What it means for us: His technical leadership is crucial for evaluating and integrating new solutions, especially those related to AI and agentic systems.",
              "claimIds": [
                "zaf-060",
                "zaf-063",
                "zaf-069"
              ]
            }
          ],
          "contactRefs": [
            {
              "name": "Ben Seri"
